/**
 * Linie 4 — "Meinungen". The learner has a life here now and starts to
 * have views on it: questions, arguments, work, plans, feelings, and
 * finally stories told in the past. CEFR A2, syntax stages 4–5.
 */

import type { Lexeme, Pos } from "../../engine/lexicon/types";
import type { Character, Line } from "../types";

const NARRATOR: Character = { id: "narrator", name: "Erzählerin", roleEn: "the narrator", voice: "katja" };
const BEN: Character = { id: "ben", name: "Ben", roleEn: "your friend from Nürnberg", voice: "killian" };
const LENA: Character = { id: "lena", name: "Lena", roleEn: "barista at the café on the Schlossplatz, from Vienna", voice: "ingrid" };
const WEBER: Character = { id: "weber", name: "Frau Weber", roleEn: "your downstairs neighbour", voice: "amala" };
const YILMAZ: Character = { id: "yilmaz", name: "Herr Yilmaz", roleEn: "runs the corner Bäckerei", voice: "conrad" };
const AMIR: Character = { id: "amir", name: "Amir", roleEn: "your colleague", voice: "florian" };

type Cefr = Lexeme["cefr"];
function w(lemma: string, pos: Pos, english: string, rank: number, cefr: Cefr, forms: string[] = [], tags?: string[]): Lexeme {
  return { id: `${lemma}:${pos}`, lemma, pos, english, rank, cefr, forms, ...(tags ? { tags } : {}) };
}
function n(lemma: string, gender: "der" | "die" | "das", plural: string | undefined, english: string, rank: number, cefr: Cefr, forms: string[] = []): Lexeme {
  return { id: `${lemma}:N`, lemma, pos: "N", gender, ...(plural ? { plural } : {}), english, rank, cefr, forms };
}

